// ======================= v12.3: plant inspection panel (V / hold Y) with live 3D close-up =======================
function openInsp(e){inspE=e;document.exitPointerLock?.();invT=0;invF=true;const el=$('insp');el.classList.add('on');inspFill();if(padMode)setFocus(el.querySelector('button'));sfx('ui')}
function closeInsp(){inspE=null;$('insp').classList.remove('on');setFocus(null)}
function inspFill(){const e0=inspE&&W.ents.find(x=>x.id==inspE.id);if(!e0||!e0.data.plant){if(inspE)closeInsp();return}inspE=e0;const d=e0.data,p=d.plant,S=STRAINS[p.s],st=stage6(p),i6=STAGE6.indexOf(st),q=harvQ(p),G=grade(q);
 const bar=(n,v,c)=>`<div class="ib"><span>${n}</span><i><b style="width:${Math.max(0,Math.min(100,v))}%;background:${c}"></b></i><em>${Math.round(v)}%</em></div>`;
 const yld=Math.max(1,Math.round(S.g*(d.sz||1)*(p.ph||1)*(p.ty=='a'?.8:1)*(.35+.65*p.health/100)));
 $('insp').innerHTML=`<div class="iw"><div id="inspv"></div><div class="ii"><h2 style="color:${SCOLp[p.s]}">${S.name}</h2><div class="is">${SEEDT[p.ty||'r'].n} seed · ${'★'.repeat(S.diff||1)}${'☆'.repeat(3-(S.diff||1))} difficulty${p.ph&&p.ph!=1?` · pheno ×${p.ph}`:''}</div>
 <div class="isg">${STAGE6.map((x,i)=>`<span class="${i<i6?'dn':i==i6?'cu':''}">${x}</span>`).join('')}</div>${p.dead?'<div class="iw2">☠ Dead — bag it with a Garbage Bag</div>':''}
 ${bar('💧 Moisture',d.moist??p.water,'#3fa0ff')}${bar('🧪 Nutrients',p.nutr,'#ffb36a')}${bar('❤ Health',p.health,'#5fd36a')}${(p.burn||0)>.02?bar('🔥 Nutrient burn',p.burn*100,'#ff6a4a'):''}
 <div class="ir">${d.bed?'Garden bed':(d.sz||1)<1?'Small pot':(d.sz||1)>1?'Large pot':'Medium pot'} · ${SOILQ[d.sq||0]} · ${litTxt(p)}${p.fd?` · last fed ${p.fd=='g'?'Grow (N)':p.fd=='b'?'Bloom (P-K)':'balanced'}`:''}</div>
 <div class="iq"><b class="gr g${G[0].replace('+','p')}">${G[0]}</b><div>Quality ~${q}/100 · est. ${yld}g at harvest<br><small>${tip(p,d,st)}</small></div></div>
 <button data-insp="close">Close ${padMode?bglyph(1):'(V / Esc)'}</button></div></div>`;if(padMode)setFocus($('insp').querySelector('button'))}
function tip(p,d,st){if(p.dead)return 'Plants die after 8 min bone dry.';if((d.moist??0)<25)return 'Water soon — dry soil stresses the plant.';if(p.burn>.3)return 'Burned: wait until nutrients drop below 70% before feeding again.';if(p.nutr<5)return 'Hungry — leaves are yellowing. Feed nutrients.';if(!p.lit&&p.ty!='a')return 'Needs light: a grow lamp within 3 m, or daylight outdoors / in the greenhouse.';
 if(st=='veg'&&p.fd!='g')return 'Veg stage loves Grow (N) nutrients.';if((st=='flower'||st=='pre-flower')&&p.fd!='b')return 'Flowering loves Bloom (P-K) nutrients.';if(st=='ripe')return 'Ripe — harvest, dry on the rack, then cure in jars for a better grade.';return 'Looking good. Keep moisture between 40% and 100%.'}
function inspRender(){if(!inspE)return;const el=document.getElementById('inspv'),o=ENTS.get(inspE.id);if(!el||!o)return;const pl=o.g.userData.plant;if(!pl)return;const r=el.getBoundingClientRect();if(r.width<10)return;
 _bx.setFromObject(pl);_bx.getCenter(_it);_bx.getSize(_bs);const top=_bx.max.y-_bs.y*.18,h=Math.max(.15,_bs.y*.55);const a=performance.now()/4000;inspCam.aspect=r.width/r.height;inspCam.updateProjectionMatrix();inspCam.position.set(_it.x+Math.cos(a)*h*1.6,top+h*.15,_it.z+Math.sin(a)*h*1.6);inspCam.lookAt(_it.x,top-h*.15,_it.z);
 const y=innerHeight-r.bottom;renderer.setScissorTest(true);renderer.setScissor(r.left,y,r.width,r.height);renderer.setViewport(r.left,y,r.width,r.height);renderer.render(scene,inspCam);renderer.setScissorTest(false);renderer.setViewport(0,0,innerWidth,innerHeight)}
{const st=document.createElement('style');st.textContent=`#insp{background:transparent;z-index:40}#insp.on{display:flex}#insp .iw{display:flex;gap:18px;align-items:stretch;background:transparent;box-shadow:0 0 0 100vmax rgba(10,14,10,.45);border:2px solid #5fd36a;border-radius:18px;padding:16px;color:#eee;font:700 14px Nunito,sans-serif;max-width:92vw}
#inspv{width:min(40vw,420px);height:min(56vh,440px);border-radius:12px;border:2px solid #345;background:transparent}#insp .ii{width:min(40vw,400px);background:rgba(20,26,20,.94);border-radius:12px;padding:12px;display:flex;flex-direction:column;gap:7px}#insp h2{margin:0;font:900 26px Nunito}#insp .is{opacity:.8}
#insp .isg{display:flex;gap:3px;flex-wrap:wrap}#insp .isg span{padding:3px 6px;border-radius:6px;background:#333;font-size:11px;text-transform:uppercase;opacity:.6}#insp .isg .dn{background:#2f5a3a;opacity:.9}#insp .isg .cu{background:#5fd36a;color:#111;opacity:1}
#insp .ib{display:grid;grid-template-columns:120px 1fr 44px;align-items:center;gap:6px}#insp .ib i{height:10px;background:#333;border-radius:5px;overflow:hidden}#insp .ib b{display:block;height:100%}#insp .ib em{font-style:normal;text-align:right}
#insp .ir{opacity:.85;font-size:13px}#insp .iq{display:flex;gap:12px;align-items:center;background:#1a221a;border-radius:10px;padding:8px}#insp .gr{font:900 30px Nunito;width:56px;height:56px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#555}
#insp .gAp{background:#c9a2ff;color:#211}#insp .gA{background:#5fd36a;color:#111}#insp .gB{background:#3fa0ff}#insp .gC{background:#e0a030}#insp .gD{background:#b04030}#insp .iw2{color:#ff6a5a}#insp button{margin-top:auto;padding:10px;border-radius:10px;border:0;background:#5fd36a;color:#111;font:900 15px Nunito}#insp button.f,#insp button:focus{outline:3px solid #fff}`;document.head.appendChild(st)}

// ---------- v19 graphics settings panel ----------
var gfxDraft=null;function gfxUI(){const P=$('gfxopts');if(!P)return;const g=gfxDraft||(gfxDraft={...GFX});
 const sel=(id,lab,opts,v)=>`<p class="gopt">${lab} <select id="g_${id}" style="font:900 16px Nunito">${opts.map(([k,n])=>`<option value="${k}"${String(k)==String(v)?' selected':''}>${n}</option>`).join('')}</select></p>`;
 P.innerHTML=sel('preset','Preset',[...PRESETS.map((p,i)=>[i,p.n]),[-1,'Custom']],g.preset)+Object.keys(LABEL).map(k=>sel(k,LABEL[k],OPTS[k],g[k])).join('')+`<p class="sub" id="gfxnote">${JSON.stringify(g)==JSON.stringify(GFX)?'Current settings':'Changed — press Apply'} · GPU auto-detect picks a default</p>`;
 P.querySelectorAll('select').forEach(el=>el.onchange=()=>{const k=el.id.slice(2),v=isNaN(+el.value)?el.value:+el.value;if(k=='preset'){gfxDraft=v<0?{...gfxDraft,preset:-1}:{...PRESETS[v],preset:v}}else{gfxDraft={...gfxDraft,[k]:v,preset:-1}}for(const q of P.querySelectorAll('select')){const kk=q.id.slice(2);q.value=String(gfxDraft[kk])}$('gfxnote').textContent=(JSON.stringify(gfxDraft)==JSON.stringify(GFX)?'Current settings':'Changed — press Apply')+' · GPU auto-detect picks a default'})}
function gfxApply(){saveGfx(gfxDraft||GFX);if(game&&W){try{document.querySelector('[data-a=savegame]')?.click()}catch(e){}}setTimeout(()=>location.reload(),game?600:50)}
